extern "C" void working_set_capacity_sweep_launch(const float*,float*,float*,int,int,int,cudaStream_t);
static inline uint32_t next_u32(uint32_t*s){*s=(*s)*1103515245u+12345u;return*s;}
static void seed_tensor(float*p,size_t n,uint32_t seed){uint32_t st=seed*2654435761u+1u;for(size_t i=0;i<n;++i){double r=(double)next_u32(&st)/4294967296.0;p[i]=(float)(-1.0+2.0*r);}}
static void fail(const char*m,int rc){fprintf(stderr,"working_set_capacity_sweep_run: %s (rc=%d: %s)\n",m,rc,cudaGetErrorString((cudaError_t)rc));exit(1);}
static uint32_t parse_u32(const char*n,const char*t,uint32_t max,bool zero_ok){char*e=nullptr;errno=0;unsigned long long v=strtoull(t,&e,10);if(t[0]<'0'||t[0]>'9'||errno||!e||*e||v>max||(!zero_ok&&v==0)){fprintf(stderr,"working_set_capacity_sweep_run: out_of_domain: invalid %s: %s\n",n,t);exit(2);}return(uint32_t)v;}
int main(int argc,char**argv){int working_set_bytes=8192,accesses=64,warps=4;uint32_t seed=42;const char*shape="correctness_00";bool summary=false;for(int i=1;i<argc;++i){if(!strcmp(argv[i],"--working-set-bytes")&&i+1<argc)working_set_bytes=(int)parse_u32("working-set-bytes",argv[++i],INT_MAX,false);else if(!strcmp(argv[i],"--accesses")&&i+1<argc)accesses=(int)parse_u32("accesses",argv[++i],INT_MAX,false);else if(!strcmp(argv[i],"--warps")&&i+1<argc)warps=(int)parse_u32("warps",argv[++i],INT_MAX/32,false);else if(!strcmp(argv[i],"--seed")&&i+1<argc)seed=parse_u32("seed",argv[++i],UINT32_MAX,true);else if(!strcmp(argv[i],"--shape-point")&&i+1<argc)shape=argv[++i];else if(!strcmp(argv[i],"--summary"))summary=true;else{fprintf(stderr,"working_set_capacity_sweep_run: unknown arg %s\n",argv[i]);return 2;}}if(!*shape||strspn(shape,"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")!=strlen(shape)||working_set_bytes%4){fprintf(stderr,"working_set_capacity_sweep_run: out_of_domain: invalid label or byte alignment\n");return 2;}uint64_t set64=(uint64_t)working_set_bytes/4;if(set64<32||set64>INT_MAX){fprintf(stderr,"working_set_capacity_sweep_run: out_of_domain: working set overflow\n");return 2;}size_t n=(size_t)set64,bytes=n*sizeof(float),output=(size_t)warps*32,output_bytes=output*sizeof(float),free_bytes=0,total_bytes=0;cudaError_t rc=cudaMemGetInfo(&free_bytes,&total_bytes);if(rc)fail("memory query",rc);if(bytes+output_bytes>free_bytes/2){fprintf(stderr,"working_set_capacity_sweep_run: out of memory: requested shape exceeds free device memory\n");return 1;}float*h_in=(float*)malloc(bytes),*h_out=(float*)malloc(output_bytes);if(!h_in||!h_out){fprintf(stderr,"working_set_capacity_sweep_run: out of memory: host allocation\n");return 1;}seed_tensor(h_in,n,seed);float*d_in=nullptr,*d_out=nullptr,*d_sink=nullptr,h_sink=0;rc=cudaMalloc(&d_in,bytes);if(rc)fail("mc in",rc);rc=cudaMalloc(&d_out,output_bytes);if(rc)fail("mc out",rc);rc=cudaMalloc(&d_sink,sizeof(float));if(rc)fail("mc sink",rc);rc=cudaMemset(d_out,0xff,output_bytes);if(rc)fail("memset out",rc);rc=cudaMemset(d_sink,0xff,sizeof(float));if(rc)fail("memset sink",rc);rc=cudaMemcpy(d_in,h_in,bytes,cudaMemcpyHostToDevice);if(rc)fail("H2D",rc);working_set_capacity_sweep_launch(d_in,d_out,d_sink,(int)n,accesses,warps,0);rc=cudaGetLastError();if(rc)fail("launch",rc);rc=cudaDeviceSynchronize();if(rc)fail("sync",rc);rc=cudaMemcpy(h_out,d_out,output_bytes,cudaMemcpyDeviceToHost);if(rc)fail("D2H",rc);rc=cudaMemcpy(&h_sink,d_sink,sizeof(float),cudaMemcpyDeviceToHost);if(rc)fail("sink D2H",rc);size_t mismatch=0;for(size_t i=0;i<output;++i){size_t src=(i/32u)*32u+(i%32u);if(!isfinite(h_out[i])||h_out[i]!=h_in[src])++mismatch;}bool correct=mismatch==0&&isfinite(h_sink);const char*shape_set=strncmp(shape,"trace_",6)==0?"trace_shapes":strncmp(shape,"timing_",7)==0?"timing_shapes":"correctness_shapes";printf("{\n  \"schema_version\":1,\n  \"slug\":\"working_set_capacity_sweep\",\n  \"shape_set\":\"%s\",\n  \"shape_point\":\"%s\",\n  \"working_set_bytes\":%d,\n  \"accesses\":%d,\n  \"warps\":%d,\n  \"correct\":%s,\n  \"mismatch_count\":%zu,\n  \"sink\":%.9g",shape_set,shape,working_set_bytes,accesses,warps,correct?"true":"false",mismatch,h_sink);if(!summary){printf(",\n  \"output\":[");for(int w=0;w<warps;++w){if(w)printf(",");printf("[");for(int l=0;l<32;++l){if(l)printf(",");printf("%.6g",h_out[w*32+l]);}printf("]");}printf("]");}printf("\n}\n");cudaFree(d_in);cudaFree(d_out);cudaFree(d_sink);free(h_in);free(h_out);return correct?0:1;}
